function productExceptSelf(nums) {
    const result = new Array(nums.length).fill(1);
    let prefix = 1;
    // Store the product strictly before each index.
    for (let i = 0; i < nums.length; i++) {
        result[i] = prefix;
        prefix *= nums[i];
    }
    let suffix = 1;
    // Multiply by the product strictly after each index.
    for (let i = nums.length - 1; i >= 0; i--) {
        result[i] *= suffix;
        suffix *= nums[i];
    }
    return result;
}
